// --- PARAMETRI ---
float scale = 50.0; // Densità degli anelli (più alto = più cerchi)
vec2 center = vec2(0.5, 0.5); // Centro dei cerchi (0.5, 0.5 è il centro della texture)

// --- LOGICA ---
// 1. Calcola la distanza del pixel corrente (u, v) dal centro
float dist = distance(vec2(u, v), center);

// 2. Crea l'onda sinusoidale basata sulla distanza
// Moltiplichiamo per 'scale' per aumentare la frequenza
float val = sin(dist * scale);

// 3. Mappiamo il risultato da -1..1 a 0..1 per il mix
float tit = (val + 1.0) * 0.5;

// 4. Mix finale
return mix(u_col1, u_col2, tit);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
    fragColor = vec4(col,1.0);
}

//IMG:/Users/dioscorid/Projects/C/presets/textures/Images/Solar System/2k_mercury.jpg
#ifdef GL_ES
precision mediump float;
#endif

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float smoothNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = noise(i);
    float b = noise(i + vec2(1.0, 0.0));
    float c = noise(i + vec2(0.0, 1.0));
    float d = noise(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) +
           (c - a) * u.y * (1.0 - u.x) +
           (d - b) * u.x * u.y;
}

float fbm(vec2 p) {
    float v = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        v += amp * smoothNoise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    float t = iTime * 0.15;
    float n = fbm(uv * 4.0 + vec2(0.0, -t));

    float smoke = smoothstep(0.3, 0.7, n);
    smoke *= smoothstep(0.0, 0.2, uv.y);

    vec3 col = vec3(smoke);
    fragColor = vec4(col, 1.0);
}

//IMG:/Users/dioscorid/Projects/C/presets/textures/Images/Solar System/2k_mercury.jpg
// --- 1. INPUT ---
vec3 c1 = u_col1;
vec3 c2 = u_col2;

// --- 2. FIX BORDI (Il segreto) ---
// Usiamo la variabile 'u_isFlat' che abbiamo creato oggi.
// Il taglio nero avviene SOLO nell'anteprima 2D.
if (u_isFlat && (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0)) {
    return vec3(0.0); 
}

// --- 3. LOGICA GRADIENTE ---
float pos = v;

// clamp assicura che sulla superficie 3D i colori si estendano 
// fino ai bordi invece di fare cose strane o invertire il gradiente.
pos = clamp(pos, 0.0, 1.0);

// --- 4. OUTPUT ---
return mix(c1, c2, pos);

