// --- CONFIGURAZIONE ---
u_min := 0;
u_max := 6.28318531;
v_min := 0;
v_max := 6.28318531;
steps := 600;
A := int(1,9);   // A e' DISCRETA: quanti tori di Hopf mostrare (1..9)

// Quante delle 9 mesh dichiarate sono davvero a schermo: le altre le spegne il
// CUTOUT in fondo (mesh > Ne). Il selettore "Mesh" del dock renderer si ferma a
// questo numero, cosi' non si puo' selezionare un toro invisibile e muoverne gli
// slider a vuoto. Senza questa riga il selettore arriverebbe a 9 sempre.
MESH_VISIBLE := A;

// --- TORI DI HOPF SOPRA I PARALLELI DELLA 2-SFERA BASE ---
// NB: non dichiarare variabili chiamate PI, pi, tau: il traduttore le
// sostituisce col valore numerico in tutto lo script.
//
// LA COSTRUZIONE. Fibrazione di Hopf h: S^3 -> S^2. Leggendo q = (x1,x2,x3,x4)
// come coppia di complessi z1 = x1 + i x2, z2 = x3 + i x4:
//
//     h(q) = ( 2 Re(z1 conj z2), 2 Im(z1 conj z2), |z1|^2 - |z2|^2 )
//
// I DUE POLI (0,0,0,+-1) hanno z1 = 0, quindi h = (0,0,-1): stanno sulla STESSA
// fibra, quella sopra il POLO SUD della base. Quella fibra e' il grande cerchio
//     C34 = { (0, 0, cos s, sin s) }
// che infatti passa per (0,0,0,+1) a s = +PI/2 e per (0,0,0,-1) a s = -PI/2.
// La fibra sopra il polo NORD e' il cerchio complementare C12 = {(cos s,sin s,0,0)}.
//
// SOLLEVAMENTO DI UN PARALLELO. Il parallelo della base a colatitudine theta
// (theta = 0 polo nord, PI/2 equatore, PI polo sud) ha preimmagine il toro
//     x1^2 + x2^2 = cos^2(theta/2)      x3^2 + x4^2 = sin^2(theta/2)
// perche' la terza componente di h vale |z1|^2 - |z2|^2 = cos(2r) con r = theta/2.
// Dunque il legame fra il parallelo della base e il raggio del toro e'
//
//     r = theta / 2         (verificato: h e' costante lungo la fibra a 4e-16)
//
// E L'EQUATORE DA' IL TORO DI CLIFFORD. A theta = PI/2 si ha r = PI/4, cioe'
//     |z1| = |z2| = 1/sqrt(2)
// che e' esattamente il toro di Clifford: l'unico toro di Hopf EQUIDISTANTE
// dalle due fibre polari C12 e C34, e quello che divide S^3 in due tori solidi
// congruenti (decomposizione di Heegaard). Verificato per sollevamento diretto:
// |(x1,x2)| - cos(PI/4) = 1.1e-16 sull'intera griglia.
//
// LE FAMIGLIE SULLO SLIDER A. Ogni valore di A mostra ESATTAMENTE A tori, e la
// regola e' semplice: A DISPARI include l'equatore (il toro di Clifford), A PARI
// no; il resto sono COPPIE simmetriche rispetto all'equatore (r e PI/2 - r).
//
//   A = 1 -> PI/4                                     (solo l'equatore)
//   A = 2 -> PI/8, 3PI/8                              (1 coppia)
//   A = 3 -> PI/4 + la coppia di A=2                  (equatore + 1 coppia)
//   A = 4 -> PI/12, PI/6 + simmetrici                 (2 coppie)
//   A = 5 -> PI/4 + le coppie di A=4                  (equatore + 2 coppie)
//   A = 6 -> PI/16, PI/8, 3PI/16 + simmetrici         (3 coppie)
//   A = 7 -> PI/4 + le coppie di A=6                  (equatore + 3 coppie)
//   A = 8 -> PI/20, PI/10, 3PI/20, PI/5 + simmetrici  (4 coppie)
//   A = 9 -> PI/4 + le coppie di A=8                  (equatore + 4 coppie)
// In gradi: A=6 da' 11.25/22.5/33.75 e i simmetrici, A=8 da' 9/18/27/36.
//
// FORMULA CHIUSA (verificata per A = 1..9): con m = floor(A/2) coppie, la
// famiglia base e'
//     r_k = k * PI / (4 (m+1))      k = 1..m
// e ogni r_k porta con se' il simmetrico PI/2 - r_k. Con m+1 al denominatore i
// raggi base restano SEMPRE sotto PI/4 (il massimo e' m/(4(m+1)) < 1/4), quindi
// nessun simmetrico cade sull'equatore: mai due mesh sovrapposte.
// Le coppie sono equispaziate fra la fibra polare e l'equatore: con A = 4 i
// paralleli base stanno a 1/3 e 2/3 della strada, con A = 6 a 1/4, 2/4, 3/4.
//
// ORDINE DELLE MESH: mesh 0 e' l'equatore quando esiste (A dispari), poi le
// coppie in ordine, base e simmetrico alternati. Cosi' A = 1 mostra il caso
// fondamentale e non un toro laterale, e alzando A i tori si AGGIUNGONO senza
// che quelli gia' presenti cambino posto... con l'eccezione voluta dalla
// specifica: passando da un A pari al successivo dispari si aggiunge l'equatore,
// mentre passando da dispari a pari cambia TUTTA la famiglia (il denominatore
// 4(m+1) cresce), quindi i tori si ridistribuiscono. E' inevitabile: le famiglie
// pari e dispari hanno spaziature diverse. Essendo tori di
// Hopf a r distinto sono ANNIDATI e DISGIUNTI (distanza minima 0.39): nessuna
// compenetrazione da rimuovere.
// CONVENZIONE DI r: qui r e' l'angolo tale che |z1| = cos r, |z2| = sin r,
// cioe' la distanza dalla fibra C12 (polo NORD). La distanza dalla fibra C34
// (quella dei due poli (0,0,0,+-1)) e' quindi PI/2 - r: 67.5, 45, 22.5 deg.
// Il toro a r = PI/8 e' percio' quello STRETTO attorno a C12 e LARGO attorno a
// C34; a 3PI/8 e' il viceversa; a PI/4 e' a 45 deg da entrambe.
//
// RELAZIONE COL LABIRINTO DI CLIFFORD. E' la STESSA costruzione dei preset
// "Clifford Labyrinth", semplificata: la' ci sono 6 tubi, uno per ogni COPPIA DI
// INDICI {i,j}, tutti allo STESSO raggio, attorno ai 6 grandi cerchi C_ij; qui
// c'e' UNA SOLA coppia di poli -- un solo asse, la fibra C34 -- e sono i RAGGI a
// variare. Verificato che l'insieme di punti coincide con quello del tubo del
// labirinto attorno a C34 (1600 punti su 1600). Conseguenza importante: nel
// labirinto i tubi CONDIVIDONO un indice e si compenetrano, per cui il cutout
// deve rimuovere le pareti interne; qui i tori sono concentrici e disgiunti,
// quindi il cutout non ha nulla da tagliare e serve solo allo slider A.
//
// --- NOTA SULLE ROTAZIONI 4D (limite noto, accettato) ---
// Con le rotazioni omega (XW) e phi (YW) il bordo mostra increspature che
// alzando gli steps si attenuano ma non scompaiono. NON e' un difetto della
// superficie ne' della mesh: e' il CAP della stereografica.
// stereoS3 calcola rad = min(sqrt((1+w)/(1-w)), 12): vicino a w = 1 il raggio
// vero tende a infinito e il min appoggia tutti quei vertici sulla stessa sfera
// di raggio 12, appiattendo la geometria -> profilo tagliato.
// Perche' proprio omega e phi: mescolano un x del fattore GRANDE con w, che sta
// nel PICCOLO, e cos^2 r + sin^2 r = 1 esatto -> il polo di proiezione viene
// RAGGIUNTO (misurato w = 1.000000). psi (ZW) invece mescola x3 e x4, entrambi
// nel fattore piccolo: la combinazione vale sin r * sin(u - t), limitata da
// sin r, e w resta a 0.707 a ogni angolo -> con psi il difetto NON compare.
// Gli steps non bastano perche' la zona oltre soglia e' un'AREA del dominio: la
// frazione di vertici clampati resta ~0.44% a qualunque risoluzione.
// Non e' aggirabile nello script: i due fattori hanno angoli indipendenti, quindi
// |(x1,x4)| = 1 per QUALSIASI r, e una pre-rotazione (rigida) non cambia nulla.
// PER RUOTARE SENZA ARTEFATTI: usare psi.
// --- COSTO CON A ALTO ---
// Le nove mesh esistono sempre; quelle oltre A vengono scartate dal cutout, ma i
// loro vertici sono comunque generati. I passi dichiarati qui sotto sono una
// PROPORZIONE riscalata dallo slider Steps, quindi il conto e' 9*(S+1)^2 vertici
// con lo slider a S: 364k a 200, 3.3M a 600, 9.0M a 1000. Sui dispositivi con
// watchdog GPU conviene tenere Steps basso quando si alza A.
//
// --- MULTI-MESH: un toro per griglia ---
// Tre mesh indipendenti, `mesh` = 0, 1, 2 sceglie il parallelo. Con una griglia
// sola servirebbero v su [0,6*PI], un selettore per ramo, il riscalamento di
// chiusura e DUE bande di guardia nel cutout per scartare i quad di giunzione
// (che lascerebbero due solchi circolari). Nulla di tutto questo serve piu':
// nessun quad puo' collegare due mesh separate.
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END

// --- RAGGIO DI QUESTA MESH: FORMULA CHIUSA ---
// Niente elenco di indicatori: con 5 mesh (e 9 nello step successivo) una catena
// di I_k diventerebbe illeggibile e va riscritta a ogni ampliamento. Qui il
// raggio si ricava da (mesh, A) in forma chiusa, senza if/else.
// PI/4 = 0.78539816, PI/2 = 1.57079633.
float Ne = clamp(floor(clamp(A, 1.0, 9.0) + 0.5), 1.0, 9.0);

float mm  = floor(Ne * 0.5);          // numero di COPPIE simmetriche
float odd = Ne - 2.0 * mm;            // 1 se A e' dispari: c'e' l'equatore

// isEq vale 1 SOLO sulla mesh 0 quando A e' dispari (l'equatore sta la').
float isEq = odd * (1.0 - step(0.5, mesh));

// Indice dentro l'elenco delle coppie: salta la mesh dell'equatore se c'e'.
float j  = mesh - odd;
float kk = floor(j * 0.5) + 1.0;      // quale coppia, 1..mm
float sg = j - 2.0 * floor(j * 0.5);  // 0 = raggio base, 1 = simmetrico

// Raggio base della coppia kk, e il suo simmetrico rispetto all'equatore.
// NB: PI/2 e' scritto 2*P4 e NON 1.57079633. Le due costanti troncate non sono
// esattamente l'una il doppio dell'altra (differiscono di 1e-8), e i due membri
// di una coppia simmetrica ne uscivano diversi di 1.27e-08: sotto l'epsilon di
// float32, quindi invisibile, ma con 2*P4 la simmetria e' esatta al bit e non
// dipende dalla precisione della GPU.
float P4 = 0.78539816;
float rb = kk * P4 / (mm + 1.0);
float rp = mix(rb, 2.0 * P4 - rb, sg);

// L'equatore vince sulla mesh 0 (dove j sarebbe negativo e rp non significativo).
float r = mix(rp, P4, isEq);

// theta = 2r e' la colatitudine del parallelo sulla 2-sfera base (r = theta/2,
// vedi sopra): non serve al calcolo, la teniamo solo come promemoria.

float cr = cos(r);
float sr = sin(r);

// --- PARAMETRIZZAZIONE PER FIBRE ---
// Sollevamento del parallelo (theta, phi) con parametro di fibra sfib:
//     z1 = cos(r) e^{i(phi+sfib)}      z2 = sin(r) e^{i sfib}
// Qui u = sfib corre LUNGO LA FIBRA (grande cerchio di S^3, cerchio di Villarceau
// visto in stereografica) e v = phi corre lungo il parallelo della base.
// DIFFERENZA DAI PRESET DEL LABIRINTO (verificata, non e' una sfumatura).
// Nel labirinto la parametrizzazione e' (cR cos u, cR sin u, sR cos v, sR sin v):
// u e v sono i due cerchi FATTORI del toro, e sono cerchi PICCOLI (raggi cos r e
// sin r, non 1). Lungo ENTRAMBE quelle direzioni la mappa di Hopf VARIA -- lo
// spread misurato e' 1.414, il massimo possibile -- quindi nel labirinto NESSUNA
// linea coordinata e' una fibra: le fibre sono le DIAGONALI (1,1) di quella
// griglia.
// Qui invece la sostituzione phi -> phi + sfib "raddrizza" le diagonali sulle
// linee u = cost: l'INSIEME di punti e' identico (1600 punti su 1600 coincidono
// col tubo del labirinto attorno a C34), ma la griglia e' ruotata di modo che
// u corra lungo la fibra. Conseguenza visibile: le linee del wireframe a v
// costante SONO le fibre di Hopf -- grandi cerchi di S^3 (centro nell'origine,
// raggio 1.000000), cerchi di Villarceau in stereografica -- e si vede che due
// fibre distinte sono ALLACCIATE (linking number 1).
// Se si vuole la griglia "da labirinto" basta togliere il + sfib dalle prime due
// componenti: la superficie non cambia, cambia solo come la si percorre.
// NB: la variabile NON si puo' chiamare 's': quel nome e' riservato alla
// costante S dello slider, che il motore inietta come `float s` in ogni script
// (glwidget.cpp, generateGlslHelperVars) -> "'s' : redefinition".
float sfib = u;
float phi = v;

// NB: il validatore in inputvalidator.cpp pretende la forma letterale del
// return con vec3 o vec4 aperto subito dopo: assegnare a una variabile e
// restituirla viene RIFIUTATO. Inoltre conta le parentesi su tutto il testo,
// COMMENTI INCLUSI: non scriverne di spaiate qui.
return vec4(
    cr * cos(phi + sfib),
    cr * sin(phi + sfib),
    sr * cos(sfib),
    sr * sin(sfib)
);

